ROOT=Path(sys.argv[1] if len(sys.argv)>1 else ".").resolve()

def patch_by_offsets(rel, expected_sha, target_sha, ops):
    p=ROOT/rel; s=p.read_text()
    got=hashlib.sha256(s.encode()).hexdigest(); assert got==expected_sha, f"{rel}: baseline SHA drift {got}"
    out=[]; pos=0
    for i1,i2,new in ops: out.append(s[pos:i1]); out.append(new); pos=i2
    out.append(s[pos:]); t="".join(out)
    got2=hashlib.sha256(t.encode()).hexdigest(); assert got2==target_sha, f"{rel}: target SHA drift {got2}"
    p.write_text(t)

